css:
.print-format-mv {
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 14px;
    color: #000;
    line-height: 1.6;
    padding: 20px;
}

/* Header Layout */
.header-section {
    margin-bottom: 40px;
}

.header-title {
    font-weight: bold;
    font-size: 16px;
}

.subtitle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 5px;
    width: 100%;
}

.header-subtitle {
    font-weight: bold;
    font-size: 16px;
}

.time-badge {
    font-weight: bold;
    font-size: 16px;
    text-align: right;
}

.nicht-mitglied-badge {
    color: #d9534f;
    font-weight: bold;
    font-size: 20px;
    margin-top: 5px;
}

/* Tabellen Layout für die Daten */
.data-table {
    width: 100%;
    border: 2px solid;
    margin-bottom: 30px;
}

.data-table td {
    padding: 4px 0;
    vertical-align: top;
}

/* Spalte für die Beschriftungen (Label) */
.data-table .label-col {
    width: 35%;
    font-weight: normal;
}

/* Spalte für die Werte */
.data-table .value-col {
    width: 65%;
    font-weight: normal;
}
